args.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
import { get } from 'node:http'

const cases = [
  { name: 'missing cookie and language', headers: {}, theme: 'light', language: 'Not specified' },
  { name: 'dark theme and language preferences', headers: { Cookie: 'theme=dark', 'Accept-Language': 'fr-CA,fr;q=0.9,en;q=0.8' }, theme: 'dark', language: 'fr-CA,fr;q=0.9,en;q=0.8' },
  { name: 'missing theme with language present', headers: { Cookie: 'session=example', 'Accept-Language': 'de' }, theme: 'light', language: 'de' },
]

for (const test of cases) {
  const { status, html } = await new Promise((resolve, reject) => {
    get('http://127.0.0.1:3100', { headers: test.headers }, (response) => {
      let html = ''
      response.setEncoding('utf8')
      response.on('data', chunk => { html += chunk })
      response.on('end', () => resolve({ status: response.statusCode, html }))
      response.on('error', reject)
    }).on('error', reject)
  })
  assert.equal(status, 200)
  const text = html.replace(/<"'!--.*?-->/g, '"'')
  assert.ok(text.includes("'`<p>Current theme: ${test.theme}</p>`), `${test.name}: theme`)
  assert.ok(text.includes(`<p>Preferred language: ${test.language}</p>`), `${test.name}: language`)
  console.log(`PASS: ${test.name}`)
}
NODE'

